    [11933]={name="Imperial Jewel",quality=3,ilvl=60,reqLevel=55,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay."},
    [11935]={name="Magmus Stone",quality=3,ilvl=58,reqLevel=53,sourceType="boss_drop",instructions="Drops from Magmus.",zone="Blackrock Depths",npc="Magmus"},
    [11936]={name="Relic Hunter Belt",quality=2,ilvl=20,reqLevel=15,sourceType="quest_reward",instructions="Reward from the quest 'The Absent Minded Prospector'. Pick it over the other reward choices.",zone="Darkshore",questName="The Absent Minded Prospector",lore="So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him."},
    [11945]={name="Dark Iron Ring",quality=2,ilvl=53,reqLevel=48,sourceType="object_drop",instructions="Found in a container.",zone="Searing Gorge",npc="a container"},
    [11946]={name="Fire Opal Necklace",quality=2,ilvl=52,reqLevel=47,sourceType="object_drop",instructions="Found in a container.",zone="Searing Gorge",npc="a container"},
    [11962]={name="Manacle Cuffs",quality=3,ilvl=55,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'The Love Potion'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Love Potion",lore="Oh, the pains of love! My dear Private Rocknot is immune to my charms. I am spurned! It's maddening! You must help me! We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart."},
    [11981]={name="Lead Band",quality=2,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="World drop around level 15-21.",zone="The Barrens",zoneOpen=true},
    [11993]={name="Clay Ring",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-24.",zone="The Barrens",zoneOpen=true},
    [11994]={name="Coral Band",quality=2,ilvl=25,reqLevel=20,sourceType="world_drop",instructions="World drop around level 20-26.",zone="The Barrens",zoneOpen=true},
    [11995]={name="Ivory Band",quality=2,ilvl=28,reqLevel=23,sourceType="world_drop",instructions="World drop around level 23-29.",zone="Duskwood",zoneOpen=true},
    [12000]={name="Limb Cleaver",quality=2,ilvl=55,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Hurley Blackbreath'. Pick it over the other reward choices. Starts with Ragnar Thunderbrew in Dun Morogh. Objective: Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",zone="Blackrock Depths",questName="Hurley Blackbreath",lore="The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."},
    [12006]={name="Meadow Ring",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-24.",zone="The Barrens",zoneOpen=true},
    [12007]={name="Prairie Ring",quality=2,ilvl=25,reqLevel=20,sourceType="world_drop",instructions="World drop around level 20-26.",zone="The Barrens",zoneOpen=true},
    [12008]={name="Savannah Ring",quality=2,ilvl=28,reqLevel=23,sourceType="world_drop",instructions="World drop around level 23-29.",zone="Duskwood",zoneOpen=true},
    [12018]={name="Conservator Helm",quality=3,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12019]={name="Cerulean Talisman",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="World drop around level 26-33.",zone="Stranglethorn Vale"},
    [12020]={name="Thallium Choker",quality=2,ilvl=36,reqLevel=31,sourceType="world_drop",instructions="World drop around level 32-37.",zone="Stranglethorn Vale"},
    [12022]={name="Iridium Chain",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42.",zone="Stranglethorn Vale"},
    [12026]={name="Quicksilver Pendant",quality=2,ilvl=59,reqLevel=54,sourceType="world_drop",instructions="World drop around level 38-61.",zone="Eastern Plaguelands"},
    [12038]={name="Lagrave's Seal",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'The Last Element'.",zone="Blackrock Depths",questName="The Last Element",lore="There is work to be had for those venturing into the depths. The Dark Irons have mastered creation of extremely powerful golems."},
    [12040]={name="Forest Pendant",quality=2,ilvl=38,reqLevel=33,sourceType="world_drop",instructions="World drop around level 33-39.",zone="Stranglethorn Vale"},
    [12047]={name="Spectral Necklace",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31.",zone="Stranglethorn Vale"},
    [12049]={name="Splintsteel Armor",quality=2,ilvl=53,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Ribbly Screwspigot'. Pick it over the other reward choices. Starts with Yuka Screwspigot in Burning Steppes. Objective: Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",zone="Blackrock Depths",questName="Ribbly Screwspigot",lore="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."},
    [12051]={name="Brazen Gauntlets",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'A Little Slime Goes a Long Way'. Pick it over the other reward choices. Starts with Laris Geardawdle in Ironforge. Objective: Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.If you have trouble finding them, perhaps try to get more clues from Laris.",zone="Ironforge",questName="A Little Slime Goes a Long Way",lore="I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."},
    [12052]={name="Ring of the Moon",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22.",zone="The Barrens",zoneOpen=true},
    [12053]={name="Volcanic Rock Ring",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22.",zone="The Barrens",zoneOpen=true},
    [12054]={name="Demon Band",quality=2,ilvl=24,reqLevel=19,sourceType="world_drop",instructions="World drop around level 19-26.",zone="The Barrens",zoneOpen=true},
    [12056]={name="Ring of the Heavens",quality=2,ilvl=56,reqLevel=51,sourceType="world_drop",instructions="World drop around level 51-61.",zone="Eastern Plaguelands"},
    [12057]={name="Dragonscale Band",quality=2,ilvl=60,reqLevel=55,sourceType="world_drop",instructions="World drop around level 38-71.",zone="Eastern Plaguelands"},
    [12062]={name="Skilled Fighting Blade",quality=2,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Jail Break!'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",zone="Blackrock Depths",questName="Jail Break!",lore="We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."},
    [12066]={name="Shaleskin Cape",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'A Taste of Flame'. Pick it over the other reward choices. Starts with Cyrus Therepentous in Burning Steppes. Objective: Travel to Blackrock Depths and slay Bael'Gar.You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.Return the Encased Fiery Essence to Cyrus Therepentous.",zone="Blackrock Depths",questName="A Taste of Flame",lore="I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave."},
    [12083]={name="Valconian Sash",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'A Taste of Flame'. Pick it over the other reward choices. Starts with Cyrus Therepentous in Burning Steppes. Objective: Travel to Blackrock Depths and slay Bael'Gar.You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.Return the Encased Fiery Essence to Cyrus Therepentous.",zone="Blackrock Depths",questName="A Taste of Flame",lore="I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave."},
    [12108]={name="Basaltscale Armor",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs."},
    [12109]={name="Azure Moon Amice",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs."},
    [12110]={name="Raincaster Drape",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs.",proc="Equip: Improves your chance to get a critical strike by 0.5%."},
    [12112]={name="Crypt Demon Bracers",quality=2,ilvl=56,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Disharmony of Fire'. Pick it over the other reward choices. Starts with Thunderheart in Blackrock Depths. Objective: Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
    [12113]={name="Sunborne Cape",quality=2,ilvl=56,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Disharmony of Fire'. Pick it over the other reward choices. Starts with Thunderheart in Blackrock Depths. Objective: Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
    [12114]={name="Nightfall Gloves",quality=2,ilvl=56,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Disharmony of Fire'. Pick it over the other reward choices. Starts with Thunderheart in Blackrock Depths. Objective: Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
    [12247]={name="Broad Bladed Knife",quality=2,ilvl=32,reqLevel=27,sourceType="vendor",instructions="Bought from Gavin Gnarltree in Stormwind (Alliance) or Ott in Orgrimmar (Horde).",zone="Hillsbrad Foothills",npc="Ott"},
